<script setup lang="ts">
import { ref, watch, onBeforeUnmount } from 'vue'; import { useI18n } from 'vue-i18n'; import { session } from '../../services/api';
import { getFile, inspectFile, downloadOriginal, type FileRecord } from '../../services/operations'; import OperationsError from './OperationsError.vue';
import PageNotice from '../PageNotice.vue';
const props=defineProps<{fileId:string}>(); const emit=defineEmits<{changed:[]}>(); const {t}=useI18n();
const file=ref<FileRecord|null>(null), busy=ref(false), error=ref<unknown>(null), note=ref(''), decision=ref<'clean'|'rejected'|null>(null);
let run=0;async function load(){const n=++run;busy.value=true;error.value=null;file.value=null;try{const result=await getFile(props.fileId);if(n===run)file.value=result}catch(e){if(n===run)error.value=e}finally{if(n===run)busy.value=false}}onBeforeUnmount(()=>{++run});
watch(()=>props.fileId,load,{immediate:true});
async function download(){if(!file.value)return;busy.value=true;error.value=null;try{await downloadOriginal(file.value)}catch(e){error.value=e}finally{busy.value=false}}
async function inspect(){if(!file.value||!decision.value)return;busy.value=true;error.value=null;try{file.value=await inspectFile(file.value.id,file.value.row_version,decision.value,note.value);decision.value=null;note.value='';emit('changed')}catch(e){error.value=e;decision.value=null}finally{busy.value=false}}
</script>
<template><div class="page-stack"><OperationsError :error="error" inline/><PageNotice v-if="file&&session.account?.roles.some(role=>['administrator','operator'].includes(role))" inline theme="warning" :message="t('ops.api.inspectHint')"/><t-button variant="outline" :loading="busy" @click="load">{{t('ops.api.refresh')}}</t-button><template v-if="file"><t-descriptions :column="1"><t-descriptions-item :label="t('ops.delivery.file')">{{file.original_name}}</t-descriptions-item><t-descriptions-item :label="t('ops.api.size')">{{file.size_bytes.toLocaleString()}} B</t-descriptions-item><t-descriptions-item :label="t('ops.api.hash')"><span style="overflow-wrap:anywhere">{{file.sha256}}</span></t-descriptions-item><t-descriptions-item :label="t('ops.api.scan')">{{t(`ops.api.status.${file.scan_status}`)}}</t-descriptions-item><t-descriptions-item :label="t('ops.api.rowVersion')">{{file.row_version}}</t-descriptions-item></t-descriptions><t-button :disabled="busy||file.scan_status!=='clean'||file.upload_status!=='ready'" @click="download">{{t('ops.api.download')}}</t-button><template v-if="session.account?.roles.some(role=>['administrator','operator'].includes(role))"><label>{{t('ops.api.inspectReason')}}</label><t-textarea v-model="note" :maxlength="2000" :autosize="{minRows:3,maxRows:7}"/><t-space break-line><t-button :disabled="busy||!note.trim()" @click="decision='clean'">{{t('ops.api.clean')}}</t-button><t-button theme="danger" variant="outline" :disabled="busy||!note.trim()" @click="decision='rejected'">{{t('ops.api.rejectFile')}}</t-button></t-space></template></template><t-dialog :visible="decision!==null" :header="t('ops.api.confirmAction')" :confirm-btn="{content:t('ops.confirm'),loading:busy}" :cancel-btn="t('ops.cancel')" @close="decision=null" @confirm="inspect"><PageNotice inline theme="warning" :message="t('ops.api.inspectHint')"/><p style="white-space:pre-wrap">{{note}}</p></t-dialog></div></template>

